// js
// EA First Schedule para 2(5): s.60FA does not apply to a domestic employee.
const employment = ctx.subject.employment;
const on = ctx.event.on;
if (on < get(employment, 'service_started_on', get(employment, 'effective_range.from'))) return 0;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const births = get(employment, 'events', []).concat(get(employment, 'children', []).filter((child) => get(child, 'born_on', null) != null).map((child) => ({ kind: 'CHILD_BIRTH', on: child.born_on }))).filter((event) => event.kind === 'CHILD_BIRTH' && event.on <= on);
const confinements = births.map((event) => event.on).filter((date, index, all) => all.indexOf(date) === index);
const record = get(employment, 'employee_extension_data.paternity_confinements', []).find((item) => item.event_id === on);
// EA s.60FA(2): five confinements, irrespective of the number of spouses; a verified record counts those of earlier employers.
if (get(record, 'lifetime_number', confinements.length) > ctx.lookup.eligibility.max_lifetime_confinements) return 0;
// EA s.60FA(3)(b): he has notified the employer of the pregnancy; HR records the finding on the record.
if (get(record, 'notification_requirement_met', true) === false) return 0;
// EA s.60FA(1): seven consecutive days for each confinement, however many children it brought.
return ctx.lookup.grant_days / births.filter((event) => event.on === on).length;
